// ============================================================
// Normalize Payload từ soc-server-python
// Payload đã có alert_id, agent_id, event_type, severity, raw_payload
// KHÔNG cần tạo lại alert — chỉ chuẩn hóa schema
// ============================================================
const body = $json.body || $json;

function pick(...vals){
  for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; }
  return null;
}

function extractDomain(url) {
  if (!url) return null;
  try {
    const m = String(url).match(/^[a-zA-Z][a-zA-Z\d+\-.]*:\/\/([^\/:?#]+)/);
    return m ? m[1] : null;
  } catch(e) { return null; }
}

// Raw payload từ soc-server là JSON string hoặc object
let raw = {};
try {
  raw = typeof body.raw_payload === 'string' ? JSON.parse(body.raw_payload) : (body.raw_payload || {});
} catch(e) { raw = {}; }

// Trích xuất fields từ raw payload
const af = raw.all_fields || raw;
const rule = af.rule || {};
const data = af.data || {};
const win = data.win?.eventdata || {};
const sysmon = data.sysmon?.eventdata || {};
const syscheck = af.syscheck || data.syscheck || {};

// ---- Các field chính từ soc-server payload ----
const alert_id = body.alert_id || '';
const agent_id = body.agent_id || af.agent?.id || 'unknown';
const event_type = body.event_type || 'unknown';
const severity = (body.severity || 'medium').toLowerCase();
const title = body.title || 'SOC Alert';
const description = pick(body.description, rule.description, 'N/A');
const timestamp = body.timestamp || $now.toISO();

// ---- Network ----
const src_ip = pick(
  raw.src_ip, body.src_ip, data.srcip, win.sourceIp, sysmon.sourceIp,
  af.agent?.ip, 'N/A'
);
const original_url = pick(raw.url, body.url, null);
let domain = pick(raw.domain, data.domain, null);
if (!domain && original_url) domain = extractDomain(original_url);

// ---- Process / EDR ----
const process_id = pick(win.processId, sysmon.processId, data.process?.pid, raw.process_id, null);
const command_line = pick(win.commandLine, sysmon.commandLine, null);
const file_hash = pick(syscheck.sha256_after, syscheck.sha256, raw.file_hash, null);

// ---- MITRE ----
const mitre = rule.mitre || {};
const mitre_tactic = body.mitre_tactic || (Array.isArray(mitre.tactic) ? mitre.tactic.join(', ') : (mitre.tactic || 'N/A'));
const mitre_id = body.mitre_technique_id || (Array.isArray(mitre.id) ? mitre.id.join(', ') : (mitre.id || 'N/A'));

// ---- Severity number cho TheHive compat ----
const severity_num = severity === 'critical' ? 4 : severity === 'high' ? 3 : severity === 'low' ? 1 : 2;

// ---- Flatten raw fields sang markdown ----
function flattenToMd(obj) {
  const blacklist = ['providerName','providerGuid','version','task','opcode','keywords',
    'eventRecordID','threadID','channel','severityValue','message','level','eventID','systemTime','computer'];
  let result = ''; let count = 0; const MAX = 40;
  function sanitize(v){ return String(v).replace(/`/g, "'").replace(/\n/g, ' ').replace(/\r/g, ' '); }
  function walk(o){
    for (const k in o){
      if (count >= MAX) return;
      if (blacklist.includes(k)) continue;
      const v = o[k];
      if (typeof v === 'object' && v !== null && !Array.isArray(v)) { walk(v); }
      else if (v !== '' && v !== null && v !== undefined) {
        result += '* **' + k + ':** `' + sanitize(v) + '`\n';
        count++;
      }
    }
  }
  walk(obj || {});
  return result || '*(Không có dữ liệu chi tiết)*';
}

const parsed_fields_md = flattenToMd((Object.keys(data).length ? data : raw));
const raw_json_md = JSON.stringify(raw, null, 2);

return [{ json: {
  alert_id, agent_id, event_type, severity, severity_num, title, description,
  src_ip, domain, original_url, process_id, command_line, file_hash,
  mitre_tactic, mitre_id, timestamp,
  rule_id: rule.id ?? 'N/A',
  rule_level: rule.level ?? 'N/A',
  rule_groups: Array.isArray(rule.groups) ? rule.groups : [],
  confidence: raw.confidence ?? 'N/A',
  reported_by: 'soc-server-python',
  parsed_fields_md, raw_json_md
} }];

// Lưu JWT token vào biến chung để dùng trong flow
const token = $json.token || $json.access_token || '';
const norm = $('Normalize Payload').item.json;

return [{ json: {
  ...norm,
  _jwt_token: token
} }];

// ============================================================
// Build IOC Summary từ soc-server-python analyze + search
// Thay thế Cortex VT Summary + MISP check
// ============================================================
const norm = $('Normalize Payload').item.json;
const jwt = $('Save JWT Token').item.json._jwt_token;

// --- Kết quả từ Analyze IOC ---
let analyzeResult = {};
try { analyzeResult = $('Analyze IOC (SOC Server)').item.json; } catch(e) {}

// --- Kết quả từ Search Indicators DB ---
let searchResult = {};
try { searchResult = $('Search Indicators DB').item.json; } catch(e) {}

// Parse analyze result
const verdict = analyzeResult.verdict || 'unknown';
const risk_score = analyzeResult.risk_score || 0;
const detections = analyzeResult.detections || 0;
const total_engines = analyzeResult.total_engines || 0;
const ioc_tags = (analyzeResult.tags || []).join(', ');
const ioc_country = analyzeResult.details?.country || 'Unknown';
const community_score = analyzeResult.community_score || 0;
const last_analysis = analyzeResult.last_analysis || 'N/A';

// Risk level từ score
let riskLevel = 'CLEAN';
if (risk_score >= 80) riskLevel = 'CRITICAL';
else if (risk_score >= 60) riskLevel = 'HIGH';
else if (risk_score >= 40) riskLevel = 'MEDIUM';
else if (risk_score > 0) riskLevel = 'LOW';

// Parse search result (tương thích MISP format)
let ioc_exists = false;
let ioc_id = null;
let ioc_attrs = [];
try {
  const response = searchResult.response || [];
  if (Array.isArray(response) && response.length > 0) {
    ioc_exists = true;
    ioc_id = response[0]?.Event?.id || null;
    ioc_attrs = response[0]?.Event?.Attribute || [];
  }
} catch(e) {}

// Build summary markdown
const ioc_summary_md = `🛡 **IOC Analysis — soc-server-python**

### Risk Level
• ${riskLevel}

### Detection
• Verdict: ${verdict}
• Risk Score: ${risk_score}/100
• Detections: ${detections}/${total_engines} engines
• Community Score: ${community_score}

### Classification
• Tags: ${ioc_tags || 'None'}
• Country: ${ioc_country}

### Indicator Database
• Exists in DB: ${ioc_exists ? 'YES (seen before)' : 'NO (new IOC)'}
• IOC ID: ${ioc_id || 'N/A'}
• Attributes found: ${ioc_attrs.length}

### Last Analysis
• ${last_analysis}`;

return [{ json: {
  ...norm,
  _jwt_token: jwt,
  ioc_verdict: verdict,
  ioc_risk_level: riskLevel,
  ioc_risk_score: risk_score,
  ioc_detections: detections,
  ioc_total_engines: total_engines,
  ioc_tags,
  ioc_country,
  ioc_exists,
  ioc_id,
  ioc_attrs: ioc_attrs.slice(0, 15),
  ioc_summary_md
} }];

const norm = $('Build IOC Summary').item.json;
return [{ json: {
  ...norm,
  action: 'block_ip',
  reason: 'DDoS được soc-server-python xác nhận. Phản ứng tức thời block IP theo rule-based policy.',
  recommendation: 'Đề xuất chặn ngay IP nguồn qua SOAR callback để ngăn tấn công tiếp diễn. Kiểm tra firewall log sau 30 phút.',
  ai_used: false,
  ai_verdict: null,
  ai_confidence: 1.0
} }];

const norm = $('Build IOC Summary').item.json;
return [{ json: {
  ...norm,
  action: 'log_only',
  reason: 'Phishing được ghi nhận theo chính sách hiện tại. Không tự động chặn domain - chờ SOC analyst xác minh.',
  recommendation: 'SOC analyst cần xác minh URL/domain trước khi block. Kiểm tra email header, screenshot phishing page nếu có.',
  ai_used: false,
  ai_verdict: null,
  ai_confidence: 0.8
} }];

// ============================================================
// Parse AI Result từ Ollama
// ============================================================
const prep = $('Build AI Prompt').item.json;

// Bắt lỗi kết nối Ollama
const errorData = $json.error;
if (errorData) {
  let reason = errorData.message || 'Không xác định';
  if (errorData.code === 'ECONNREFUSED') reason = 'Ollama chưa bật hoặc sai port.';
  if (errorData.code === 'ETIMEDOUT') reason = 'Ollama quá tải, không trả lời kịp.';
  if (errorData.code === 'ENOTFOUND') reason = 'Không tìm thấy địa chỉ IP của Ollama.';
  return [{ json: {
    action: 'log_only',
    reason: '⚠️ Lỗi kết nối AI: ' + reason,
    recommendation: 'Kiểm tra Ollama service tại host.docker.internal:11434. SOC analyst xử lý thủ công.',
    ai_used: true, ai_verdict: 'unknown', ai_confidence: 0,
    alert_id: prep.alert_id,
    src_ip: prep.src_ip, agent_id: prep.agent_id, process_id: prep.process_id,
    timestamp: prep.timestamp, description: prep.description, severity: prep.severity,
    ioc_summary_md: prep.ioc_summary_md, _jwt_token: prep._jwt_token
  } }];
}

let rawOutput = ($json.response ?? '').toString();
rawOutput = rawOutput.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
if (!rawOutput) {
  parsed = { verdict: 'false_positive', action: 'none', reason: '⚠️ Ollama không trả về dữ liệu. Kiểm tra service Ollama / model gemma3:4b.', confidence: 0 };
} else {
  try { parsed = JSON.parse(rawOutput); }
  catch (e) {
    const preview = rawOutput.length > 300 ? rawOutput.slice(0, 300) + '...' : rawOutput;
    parsed = { verdict: 'false_positive', action: 'none', reason: '⚠️ AI trả lời sai JSON: ' + e.message + ' | Raw: ' + preview, confidence: 0 };
  }
}

if (typeof parsed !== 'object' || parsed === null || (!('verdict' in parsed) && !('action' in parsed))) {
  const preview = rawOutput.length > 300 ? rawOutput.slice(0, 300) + '...' : rawOutput;
  parsed = { verdict: 'false_positive', action: 'none', reason: '⚠️ AI trả JSON sai schema | Raw: ' + preview, confidence: 0 };
}

const action = (parsed.action ?? 'none') === 'none' ? 'log_only' : parsed.action;

const defaultRec = {
  block_ip: 'Đề xuất chặn ngay IP nguồn qua SOAR callback để ngăn tấn công tiếp diễn.',
  kill_process: 'Đề xuất buộc dừng tiến trình độc hại trên endpoint và cách ly máy nếu cần.',
  block_url: 'Đề xuất block domain/URL trên DNS/Firewall và thông báo user bị ảnh hưởng.',
  log_only: 'Chưa đủ cơ sở hành động tự động, SOC analyst xác minh thủ công.'
};
const recommendation = (parsed.recommendation && String(parsed.recommendation).trim())
  || defaultRec[action]
  || 'SOC analyst cần đánh giá thủ công.';

return [{ json: {
  action, recommendation,
  reason: parsed.reason ?? 'N/A',
  ai_used: true, ai_verdict: parsed.verdict ?? 'false_positive', ai_confidence: parsed.confidence ?? 0,
  alert_id: prep.alert_id,
  src_ip: prep.src_ip, agent_id: prep.agent_id, process_id: prep.process_id,
  timestamp: prep.timestamp, description: prep.description, severity: prep.severity,
  ioc_summary_md: prep.ioc_summary_md, _jwt_token: prep._jwt_token
} }];

